```python
from typing import Optional, List

def binary_search(arr: List[int], target: int) -> Optional[int]:
    """Find the first index of `target` in `arr`, or None if not found.

    Time complexity: O(log n)
    Space complexity: O(1)
    """

    # validate the input
    if not arr or target is None:
        return None

    # get the low and high bounds of the search space
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        # check if the middle element matches the target
        if arr[mid] == target:
            # return the index
            return mid

        # if the middle element is less than the target, update the low bound
        elif arr[mid] < target:
            low = mid + 1

        # if the middle element is greater than the target, update the high bound
        else:
            high = mid - 1

    # if the target is not found, return None
    return None

```

To use this function, you can do something like this:

```python
arr = [1, 2, 3, 4, 5]
target = 4

result = binary_search(arr, target)

print(result)  # Output: 3

```

