    arr = [1, 2, 3, 4, 5]
    target = 4
    assert binary_search(arr, target) == 3

def test_binary_search_not_found():
    arr = [1, 2, 3, 4, 5]
    target = 6
    assert binary_search(arr, target) == None

def test_binary_search_empty_arr():
    arr = []
    target = 1
    assert binary_search(arr, target) == None

def test_binary_search_none_target():
    arr = [1, 2, 3]
    target = None
    assert binary_search(arr, target) == None
